fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    // For each index j, if j == i use v[i], otherwise 0.0
    v.iter()
        .enumerate()
        .map(|(j, &x)| if j == i { x } else { 0.0 })
        .collect()
}

fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        matrix.push(create_row(&v, i));
    }
    matrix
}

// Example usage and simple test
fn main() {
    let v = vec![1.0_f32, 2.5, -3.2];
    let m = diagflat(v);
    for row in &m {
        println!("{:?}", row);
    }
    // This will print:
    // [1.0, 0.0, 0.0]
    // [0.0, 2.5, 0.0]
    // [0.0, 0.0, -3.2]
}